import sharp from 'sharp';
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {createApp} from '../src/server.mjs';
import {uid,dayKey,dateRange,validateMaterial,ipMatches} from '../src/security.mjs';
import {verifyCallback,LarkService,buildCard} from '../src/lark.mjs';
import {testMaterial} from './fixtures/markdown.mjs';
const password='test-admin-password-unique-987';process.env.ADMIN_PASSWORD=password;
async function fixture(options={}){const runtime=fs.mkdtempSync(path.join(os.tmpdir(),'crm-training-test-'));const app=createApp({seedMaterial:testMaterial(),runtime,origin:'http://training.test',scheduler:false,...options});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+app.server.address().port;
 function client(autoSecurity=true){const email=uid()+'@example.test';const cookies={};let csrf='';return {async request(url,method='GET',body,extra={}){if(url==='/api/access'&&body&&body.contact===undefined&&body.email===undefined)body={...body,contact:email};const r=await fetch(base+url,{method,headers:{cookie:Object.entries(cookies).map(([k,v])=>k+'='+v).join('; '),'content-type':'application/json',...(method!=='GET'?{'x-csrf-token':csrf}:{}),...extra},body:body===undefined?undefined:JSON.stringify(body)});for(const h of r.headers.getSetCookie()){const [kv]=h.split(';');const at=kv.indexOf('=');cookies[kv.slice(0,at)]=kv.slice(at+1)}const data=r.headers.get('content-type')?.startsWith('image/')?Buffer.from(await r.arrayBuffer()):await r.json();if(data.csrf)csrf=data.csrf;if(autoSecurity&&url==='/api/access'&&data.security)return this.request('/api/security/complete','POST',{mode:'password',secret:'test-security-password-987',confirm:'test-security-password-987'});return {status:r.status,data,headers:r.headers}},async session(){return this.request('/api/session')},async login(){await this.session();return this.request('/api/admin/login','POST',{username:'admin',password})},async select(code='PAMM',name='Learner'){await this.session();return this.request('/api/access','POST',{code,name,consent:true})}}}
 return {...app,client,base,async cleanup(){await app.close();fs.rmSync(runtime,{recursive:true,force:true})}}}

test('synthetic fixture has 28 paired pages and valid stable IDs',()=>{const material=testMaterial();validateMaterial(material);assert.deepEqual(material.lessons.map(l=>l.pages.length),[9,10,9]);for(const p of material.lessons.flatMap(l=>l.pages)){assert(p.body.en.length>200);assert(p.speaker.en.length>70)}assert.throws(()=>validateMaterial({lessons:[]}));assert(ipMatches('203.0.113.9','203.0.113.0/24'));assert(!ipMatches('203.0.114.9','203.0.113.0/24'));assert(ipMatches('2001:db8::1','2001:db8::/32'));assert.deepEqual(dateRange('2026-10-31','2026-10-31'),['2026-10-30T16:00:00.000Z','2026-10-31T16:00:00.000Z']);assert.throws(()=>dateRange('2026-02-31','2026-03-01'))});

test('case-insensitive code selects course; no content before approval; request bound to device',async()=>{const f=await fixture();try{const a=f.client(),b=f.client(),admin=f.client();assert.equal((await a.select('PaMm')).status,200);assert.equal((await a.request('/api/course')).status,403);assert.equal((await a.request('/api/admin/material?course=pamm')).status,403);const missing=await fetch(f.base+'/content/pamm.json');assert.equal(missing.status,404);const r=await a.request('/api/requests','POST',{}),duplicate=await a.request('/api/requests','POST',{});assert.equal(r.data.id,duplicate.data.id);await b.select();assert.equal((await admin.login()).status,200);const approval=await admin.request('/api/admin/requests','POST',{id:r.data.id,status:'approved',hours:168});assert.equal(approval.status,200);const material=await a.request('/api/course');assert.equal(material.status,200);assert(!('speaker' in material.data.material.lessons[0].pages[0]));assert.equal((await b.request('/api/course')).status,403);await admin.request('/api/admin/revoke','POST',{id:r.data.id});assert.equal((await a.request('/api/course')).status,403);const forged=await b.request('/api/session','GET',undefined,{'x-real-ip':'203.0.113.9','x-forwarded-for':'203.0.113.9'});assert.equal(forged.data.ip,'127.0.0.1')}finally{await f.cleanup()}});

test('IP allowlist, expiry, CSRF, cross-origin and course isolation',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await a.select();assert.equal((await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1',hours:1})).status,201);assert.equal((await a.request('/api/course')).status,200);assert.equal((await a.request('/api/note','PUT',{page:'manager-01',body:'bad'},{'x-csrf-token':'wrong'})).status,403);assert.equal((await a.request('/api/note','PUT',{page:'manager-01',body:'bad'},{origin:'https://evil.test'})).status,403);assert.equal((await admin.request('/api/admin/courses','POST',{id:'smartcopy',title:{zh:'智能跟单',en:'Smart Copy'},code:'SmartCopy'})).status,201);assert.equal((await admin.request('/api/admin/courses','POST',{id:'duplicate',title:{zh:'冲突',en:'Conflict'},code:'pamm'})).status,409);await a.select('smartcopy');assert.equal((await a.request('/api/course')).status,403);f.store.run("UPDATE whitelist SET expires='2000-01-01T00:00:00.000Z'");await a.select('pamm');assert.equal((await a.request('/api/course')).status,403)}finally{await f.cleanup()}});

test('private notes stay private; questions reply within course/page; stable ordering and one vote',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client(),b=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select('pamm','Alice');await b.select('pamm','Bob');await a.request('/api/note','PUT',{page:'manager-01',body:'Private Alice note'});assert.equal((await b.request('/api/note?page=manager-01')).data.body,'');const q=await a.request('/api/questions','POST',{page:'manager-01',body:'<script>alert(1)</script> What is the fee?'});const reply=await b.request('/api/questions','POST',{page:'manager-01',body:'A reply',parent:q.data.id});assert.equal(reply.status,201);assert.equal((await b.request('/api/questions','POST',{page:'manager-02',body:'Cross-page reply',parent:q.data.id})).status,400);await a.request('/api/question','PATCH',{id:q.data.id,action:'vote'});await a.request('/api/question','PATCH',{id:q.data.id,action:'vote'});const list=(await b.request('/api/questions?page=manager-01&sort=oldest')).data;assert.equal(list.items[0].votes,1);assert.equal(list.items[0].children[0].body,'A reply');assert.equal((await b.request('/api/question','PATCH',{id:q.data.id,action:'remove'})).status,403)}finally{await f.cleanup()}});

test('server-clock reading, duplicate events, inactive/other-tab limits and metrics',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await a.request('/api/course');const s=(await a.session()).data;const event=(id,kind='heartbeat',tab='one')=>a.request('/api/events','POST',{id,kind,tab,page:'manager-01',language:'en',scroll:.9,seconds:99999});await event(uid(),'view');f.store.run('UPDATE read_state SET stamp=? WHERE user_id=?',Date.now()-15000,s.user.id);const id=uid(),r=await event(id);assert(r.data.seconds>=14&&r.data.seconds<=16);assert.equal((await event(id)).data.duplicate,true);f.store.run('UPDATE read_state SET stamp=? WHERE user_id=?',Date.now()-25000,s.user.id);assert.equal((await event(uid())).data.seconds,20);assert.equal((await event(uid(),'heartbeat','second')).data.seconds,0);await event(uid(),'pause','second');assert.equal((await event(uid(),'heartbeat','second')).data.seconds,0);const stats=(await admin.request('/api/admin/stats?from='+dayKey()+'&to='+dayKey())).data;assert.equal(stats.summary.visitors,1);assert(stats.summary.seconds>=34&&stats.summary.seconds<=36);assert.equal(stats.pages[0].qualified,1)}finally{await f.cleanup()}});

test('bilingual optimistic material edits, publication and rollback; annotations require admin',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await admin.request('/api/admin/select','POST',{course:'pamm'});const initial=(await admin.request('/api/admin/material?course=pamm')).data;const modified=structuredClone(initial.material);modified.lessons[0].pages[0].title.en='Revised introduction';const save=await admin.request('/api/admin/material','PUT',{course:'pamm',baseVersion:1,material:modified});assert.equal(save.data.version,2);assert.equal((await admin.request('/api/admin/material','PUT',{course:'pamm',baseVersion:1,material:modified})).status,409);assert.equal((await admin.request('/api/course')).data.version,1);await admin.request('/api/admin/publish','POST',{course:'pamm',version:2});assert.equal((await admin.request('/api/course')).data.version,2);await admin.request('/api/admin/publish','POST',{course:'pamm',version:1});assert.equal((await admin.request('/api/course')).data.version,1);delete modified.lessons[0].pages[0].body.en;assert.equal((await admin.request('/api/admin/material','PUT',{course:'pamm',baseVersion:2,material:modified})).status,400);assert.equal((await admin.request('/api/annotations','POST',{page:'manager-01',body:{zh:'批注',en:'Annotation'}})).status,201);await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();assert.equal((await a.request('/api/annotations','POST',{page:'manager-01',body:{zh:'假冒',en:'Spoof'}})).status,403)}finally{await f.cleanup()}});

test('Lark daily card creates once, updates same message, and protects uncertain delivery',async()=>{const f=await fixture();try{f.store.set('lark',{enabled:true,receiveId:'oc_test',appId:'test',appSecret:'not-real'});const service=new LarkService(f.store,'https://training.test'),calls=[];service.api=async(path,options)=>{calls.push({path,options});return {message_id:'om_test'}};assert.equal((await service.sync()).state,'updated');assert.equal((await service.sync()).state,'unchanged');assert.equal((await service.sync(true)).state,'updated');assert.equal(calls.filter(c=>c.options.method==='POST').length,1);assert.equal(calls.filter(c=>c.options.method==='PATCH').length,1);f.store.run('UPDATE cards SET state=?,message_id=NULL','sending');await assert.rejects(service.sync(true),/uncertain/)}finally{await f.cleanup()}});

test('Lark callback rejects spoofed signature, stale timestamp and unauthorized operator; replay is idempotent',async()=>{const f=await fixture();try{const cfg={encryptKey:'test-key',verificationToken:'test-token',adminOpenIds:['ou_admin']};f.store.set('lark',cfg);const a=f.client();await a.select();const request=(await a.request('/api/requests','POST',{})).data;
 const payload={schema:'2.0',header:{event_id:'event-1',event_type:'card.action.trigger',token:cfg.verificationToken},event:{operator:{open_id:'ou_admin'},action:{value:{action:'approve',requestId:request.id}}}};
 const sign=(data,stamp=String(Math.floor(Date.now()/1000)))=>{const raw=JSON.stringify(data),nonce='nonce',signature=crypto.createHash('sha256').update(stamp+nonce+cfg.encryptKey+raw).digest('hex');return {raw,headers:{'content-type':'application/json','x-lark-request-timestamp':stamp,'x-lark-request-nonce':nonce,'x-lark-signature':signature}}};
 const valid=sign(payload);assert.equal(verifyCallback(valid.raw,valid.headers,cfg).header.event_id,'event-1');assert.throws(()=>verifyCallback(valid.raw,{...valid.headers,'x-lark-signature':'invalid'},cfg));assert.throws(()=>verifyCallback(valid.raw,sign(payload,'1').headers,cfg));const bad=structuredClone(payload);bad.event.operator.open_id='ou_outsider';const denied=sign(bad);assert.equal((await fetch(f.base+'/api/lark/callback',{method:'POST',headers:denied.headers,body:denied.raw})).status,403);
 const response=await fetch(f.base+'/api/lark/callback',{method:'POST',headers:valid.headers,body:valid.raw});assert.equal(response.status,200);assert.equal(f.store.get('SELECT status FROM requests WHERE id=?',request.id).status,'approved');assert.equal((await fetch(f.base+'/api/lark/callback',{method:'POST',headers:valid.headers,body:valid.raw})).status,200);assert.equal(f.store.get('SELECT COUNT(*) AS n FROM callbacks').n,1)}finally{await f.cleanup()}});

test('Greater China IP locale defaults and manual-ready metadata',async()=>{const {languageForIp}=await import('../src/locale.mjs');for(const country of ['CN','HK','MO','TW'])assert.equal(languageForIp('127.0.0.1',()=>({country})).language,'zh');for(const country of ['US','SG','GB',''])assert.equal(languageForIp('127.0.0.1',()=>({country})).language,'en');assert.equal(languageForIp('114.114.114.114').language,'zh');const f=await fixture();try{const c=f.client();assert.equal((await c.session()).data.language,'en')}finally{await f.cleanup()}});

test('published history and stable discussions survive edits; removing published IDs is rejected',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await a.request('/api/note','PUT',{page:'manager-01',body:'Original private learning note',version:1});const q=(await a.request('/api/questions','POST',{page:'manager-01',body:'Original discussion',version:1})).data;const d=(await admin.request('/api/admin/material?course=pamm')).data;const updated=structuredClone(d.material);updated.lessons[0].pages[0].body.en='New wording, same stable topic.';await admin.request('/api/admin/material','PUT',{course:'pamm',baseVersion:1,material:updated});assert.equal((await a.request('/api/course?version=2')).status,404);await admin.request('/api/admin/publish','POST',{course:'pamm',version:2});assert.equal((await a.request('/api/note?page=manager-01')).data.body,'Original private learning note');assert.equal((await a.request('/api/questions?page=manager-01')).data.items[0].id,q.id);assert.equal((await a.request('/api/questions?page=manager-01')).data.items[0].material_version,1);const old=(await a.request('/api/course?version=1')).data;assert.equal(old.version,1);assert.notEqual(old.material.lessons[0].pages[0].body.en,'New wording, same stable topic.');updated.lessons[0].pages.splice(0,1);assert.equal((await admin.request('/api/admin/material','PUT',{course:'pamm',baseVersion:2,material:updated})).status,409)}finally{await f.cleanup()}});

test('configured system links and floating questions stay gated and course-bound',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();const home=await admin.request('/api/admin/links','POST',{course:'pamm',title:{zh:'系统主页',en:'System home'},url:'https://example.com/'});assert.equal(home.status,201);assert.equal((await admin.request('/api/admin/links','POST',{course:'pamm',page:'manager-01',title:{zh:'页面系统',en:'Page system'},url:'https://example.com/page'})).status,201);assert.equal((await admin.request('/api/admin/links','POST',{course:'pamm',title:{zh:'错误',en:'Bad'},url:'javascript:alert(1)'})).status,400);await a.select();assert.equal((await a.request('/api/course-links')).status,403);await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});assert.equal((await a.request('/api/course-links')).data.length,2);const q=await a.request('/api/questions','POST',{page:'manager-01',body:'Question from the floating button',version:1,source:'floating'});assert.equal(q.status,201);assert.equal(f.store.get('SELECT source FROM questions WHERE id=?',q.data.id).source,'floating');assert.equal((await a.request('/api/admin/links','POST',{course:'pamm',title:{zh:'越权',en:'Forbidden'},url:'https://example.com/'})).status,403)}finally{await f.cleanup()}});

test('scoped agents export questions without private fields and propose FAQ; only admins publish/choose priorities',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await a.request('/api/note','PUT',{page:'manager-01',body:'Sensitive private note'});const q=(await a.request('/api/questions','POST',{page:'manager-01',body:'Does approval mean payment?',source:'floating'})).data;const issue=(await admin.request('/api/admin/agents','POST',{name:'Semantic curator',courses:['pamm'],scopes:['read:questions','write:faq'],hours:1})).data;const agent=async(p,method='GET',body)=>{const r=await fetch(f.base+p,{method,headers:{authorization:'Bearer '+issue.token,'content-type':'application/json'},body:body?JSON.stringify(body):undefined});return {status:r.status,data:await r.json()}};const exported=await agent('/api/agent/questions?course=pamm&from='+dayKey()+'&to='+dayKey());assert.equal(exported.status,200);assert.equal(exported.data.items[0].source,'floating');for(const field of ['ip','contact','user_id'])assert(!(field in exported.data.items[0]));assert(!JSON.stringify(exported.data).includes('Sensitive private note'));assert.equal((await agent('/api/agent/questions?course=not-scoped')).status,403);const proposal=(await agent('/api/agent/faqs','POST',{course:'pamm',title:{zh:'确认是否等于付款？',en:'Does confirmation mean payment?'},answer:{zh:'不等于，仍需周期结算和风险检查。',en:'No. Periodic settlement and risk checks remain.'},questionIds:[q.id],important:true})).data;assert.equal((await a.request('/api/faqs')).data.hot.length,0);const draft=(await admin.request('/api/admin/faqs?course=pamm')).data[0];assert.equal(draft.important,false);assert.equal((await agent('/api/admin/faq/publish','POST',{id:proposal.id,revision:proposal.revision})).status,403);await admin.request('/api/admin/faq/publish','POST',{id:proposal.id,revision:proposal.revision});assert.equal((await a.request('/api/faqs')).data.hot[0].recent,1);assert.equal((await a.request('/api/faqs')).data.allTime[0].total,1);await admin.request('/api/admin/faq/important','POST',{id:proposal.id,important:true,priority:1});assert.equal((await a.request('/api/faqs')).data.important[0].id,proposal.id);await admin.request('/api/admin/agents','DELETE',{id:issue.id});assert.equal((await agent('/api/agent/faqs?course=pamm')).status,401)}finally{await f.cleanup()}});

test('daily cards use one persistent message per administrator recipient',async()=>{const f=await fixture();try{f.store.set('lark',{enabled:true,receiveType:'open_id',receiveId:'ou_a,ou_b',appId:'test',appSecret:'not-real'});const service=new LarkService(f.store,'https://training.test'),calls=[];service.api=async(p,o)=>{calls.push({p,o});return {message_id:'om_'+calls.length}};await service.sync();await service.sync();await service.sync(true);assert.equal(calls.filter(c=>c.o.method==='POST').length,2);assert.equal(calls.filter(c=>c.o.method==='PATCH').length,2);assert.equal(f.store.get('SELECT COUNT(*) AS n FROM cards').n,2)}finally{await f.cleanup()}});

test('delegated instructor tools are course-scoped, independently permissioned and immediately revocable',async()=>{const f=await fixture();try{const admin=f.client(),teacher=f.client();await admin.login();const account=(await admin.request('/api/admin/instructors','POST',{username:'teacher.one',name:'Verified Instructor',password:'teacher-password-long-987',hours:72})).data;assert(account.id);await admin.request('/api/admin/instructor-grants','PUT',{instructor:account.id,course:'pamm',hours:24,capabilities:{annotate:true,draft:true,moderate:true,stats:false,publish:false}});await teacher.session();const login=await teacher.request('/api/instructor/login','POST',{username:'TEACHER.ONE',password:'teacher-password-long-987'});assert.equal(login.status,200);assert.equal((await teacher.request('/api/admin/requests')).status,403);assert.equal((await teacher.request('/api/admin/agents')).status,403);assert.equal((await teacher.request('/api/admin/visits')).status,403);const list=(await teacher.request('/api/instructor/courses')).data;assert.equal(list.length,1);assert.equal(list[0].capabilities.publish,false);await teacher.request('/api/instructor/select','POST',{course:'pamm'});const selected=(await teacher.session()).data;assert.equal(selected.role,'instructor');assert.equal(selected.teacher,true);const published=(await teacher.request('/api/course')).data;assert(published.material.lessons[0].pages[0].speaker.en);assert.equal((await teacher.request('/api/instructor/stats?course=pamm')).status,403);const current=(await teacher.request('/api/instructor/material?course=pamm')).data;assert.equal((await teacher.request('/api/instructor/material','PUT',{course:'pamm',baseVersion:1,material:current.material})).data.version,2);assert.equal((await teacher.request('/api/instructor/publish','POST',{course:'pamm',version:2})).status,403);assert.equal((await teacher.request('/api/annotations','POST',{page:'manager-01',body:{zh:'讲师批注',en:'Instructor annotation'}})).status,201);const answer=await teacher.request('/api/questions','POST',{page:'manager-01',body:'Verified instructor explanation'});assert.equal(f.store.get('SELECT teacher FROM questions WHERE id=?',answer.data.id).teacher,1);const event=await teacher.request('/api/events','POST',{id:uid(),page:'manager-01',kind:'view',language:'en',tab:'teacher'});assert.equal(event.data.ignored,true);assert.equal(f.store.get('SELECT COUNT(*) AS n FROM visits').n,0);assert.equal(f.store.get('SELECT COUNT(*) AS n FROM events').n,0);await admin.request('/api/admin/courses','POST',{id:'smartcopy',code:'smartcopy',title:{zh:'智能跟单',en:'Smart Copy'}});assert.equal((await teacher.request('/api/instructor/material?course=smartcopy')).status,403);await admin.request('/api/admin/instructor-grants','PUT',{instructor:account.id,course:'pamm',hours:24,capabilities:{annotate:true,draft:true,moderate:true,stats:true,publish:true}});assert.equal((await teacher.request('/api/instructor/publish','POST',{course:'pamm',version:2})).status,200);const stats=(await teacher.request('/api/instructor/stats?course=pamm')).data;assert(!('learners' in stats));assert(!JSON.stringify(stats).includes('contact'));await admin.request('/api/admin/instructor-grants','DELETE',{instructor:account.id,course:'pamm'});assert.equal((await teacher.request('/api/course')).status,403);assert.equal((await teacher.request('/api/instructor/material?course=pamm')).status,403);await admin.request('/api/admin/instructors','PATCH',{id:account.id,enabled:false});assert.equal((await teacher.request('/api/instructor/courses')).status,401);await teacher.session();assert.equal((await teacher.request('/api/instructor/login','POST',{username:'teacher.one',password:'teacher-password-long-987'})).status,401)}finally{await f.cleanup()}});

test('IMPROVES scenario feedback is private per learner and retained per material version',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client(),b=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await b.select();assert.equal((await a.request('/api/check','PUT',{page:'manager-01',version:1,understood:false})).status,200);assert.equal((await b.request('/api/check?page=manager-01&version=1')).data.understood,null);const stats=(await admin.request('/api/admin/stats')).data;assert.equal(stats.summary.needExplanation,1);assert.equal(stats.pages.find(p=>p.page==='manager-01').needExplanation,1);const current=(await admin.request('/api/admin/material?course=pamm')).data;for(const page of current.material.lessons.flatMap(l=>l.pages)){assert(page.objective.zh&&page.objective.en);assert(page.exercise.question.zh&&page.exercise.answer.en)}await admin.request('/api/admin/material','PUT',{course:'pamm',baseVersion:1,material:current.material});await admin.request('/api/admin/publish','POST',{course:'pamm',version:2});assert.equal((await a.request('/api/check?page=manager-01&version=1')).data.understood,0);assert.equal((await a.request('/api/check?page=manager-01&version=2')).data.understood,null);await a.request('/api/check','PUT',{page:'manager-01',version:2,understood:true});assert.equal((await admin.request('/api/admin/stats')).data.summary.needExplanation,0)}finally{await f.cleanup()}});

