test('one upload stores two business versions under one revision with independent publication, ACL and discussions',async()=>{const {versionedSource}=await import('./fixtures/markdown.mjs');const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await admin.request('/api/admin/select','POST',{course:'pamm'});await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await a.request('/api/note','PUT',{page:'manager-01',body:'Keep v1 note'});const q1=await a.request('/api/questions','POST',{page:'manager-01',body:'Public v1 question'});const upload=await admin.request('/api/admin/material-markdown','POST',{course:'pamm',baseVersion:1,filename:'test.md',markdown:versionedSource()});assert.equal(upload.status,201);assert.equal(upload.data.revision,2);assert.equal(upload.data.summary.businessVersions.length,2);assert.equal((await a.request('/api/course?businessVersion=v2')).status,403);const preview=await admin.request('/api/course?businessVersion=v2&version=2');assert.equal(preview.status,200);assert.equal(preview.data.material.lessons[0].pages[0].id,'bv_v2--manager-01');assert.equal((await admin.request('/api/admin/publish','POST',{course:'pamm',businessVersion:'v1',version:2,confirmMarkdown:true})).status,200);assert.equal((await a.request('/api/course')).data.revision,2);assert.deepEqual((await a.request('/api/course')).data.businessVersions.map(b=>b.id),['v1']);assert.equal((await a.request('/api/note?page=manager-01')).data.body,'Keep v1 note');assert.equal((await admin.request('/api/admin/publish','POST',{course:'pamm',businessVersion:'v2',version:2,confirmMarkdown:true})).status,200);assert.equal((await a.request('/api/course?businessVersion=v2')).status,403);const h={'x-business-version':'v2'};const q2=await admin.request('/api/questions','POST',{page:'bv_v2--manager-01',version:2,body:'Private v2 question'},h);assert.equal(q2.status,201);assert.equal((await a.request('/api/questions')).data.items.length,1);assert.equal((await a.request('/api/question','PATCH',{id:q2.data.id,action:'vote'})).status,404);assert.equal((await admin.request('/api/questions','GET',undefined,h)).data.items[0].id,q2.data.id);assert.equal((await admin.request('/api/question','PATCH',{id:q1.data.id,action:'vote'},h)).status,200);const token=(await admin.request('/api/admin/agents','POST',{name:'Test agent',courses:['pamm'],scopes:['read:questions'],hours:1})).data.token;const agent={'authorization':'Bearer '+token};assert.equal((await a.request('/api/agent/questions?course=pamm&businessVersion=v2','GET',undefined,agent)).status,403);assert.equal((await a.request('/api/agent/questions?course=pamm','GET',undefined,agent)).data.items.length,1);assert.equal((await admin.request('/api/admin/business-versions','PATCH',{course:'pamm',businessVersion:'v2',visibility:'public'})).status,200);assert.equal((await a.request('/api/course?businessVersion=v2')).data.businessVersion,'v2');assert.equal((await a.request('/api/note?page=bv_v2--manager-01','GET',undefined,h)).data.body,'');assert.equal((await a.request('/api/note?page=manager-01','GET',undefined,h)).status,404)}finally{await f.cleanup()}});

