 const admin=f.client(),a=f.client(),b=f.client();await admin.login();await a.session();await b.session();
 const enter=(client,email,name)=>client.request('/api/access','POST',{code:'pamm',contact:email,name,consent:true});
 assert.equal((await enter(a,'','Alice')).status,400);assert.equal((await enter(a,'bad','Alice')).status,400);
 assert.equal((await enter(a,' Alice@Example.com ','First name')).status,200);const id=(await a.session()).data.user.id;
