 for(const [id,email] of [[x,'Legacy@example.com'],[y,' LEGACY@EXAMPLE.COM ']])f.store.run('INSERT INTO users(id,device_hash,name,contact,created) VALUES(?,?,?,?,?)',id,id,'Same nickname',email,f.store.now());
