 const pub=async(method='GET',body,extra={})=>{const r=await fetch(f.base+'/api/ppt-public'+(method==='POST'?'/extend':''),{method,headers:{authorization:'Bearer '+bearer,'x-ppt-visitor':'a'.repeat(64),'content-type':'application/json',...(method==='POST'?{origin:'http://training.test'}:{}),...extra},body:body===undefined?undefined:JSON.stringify(body)});return {status:r.status,data:await r.json(),headers:r.headers}};

