test('hosting expiry blocks new shares and extensions while preserving valid approved reading',async()=>{
 let active=true;
 const f=await fixture({hosting:{allowLegacyAdmin:true,status:()=>({active,portalUrl:'https://hosting.test/dashboard',signupUrl:'https://hosting.test/'})}});
 try{
  const admin=f.client(),reader=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await reader.select();
  f.store.set('pptPolicy:pamm',{allowAll:true,maxHours:168});
  const issued=await reader.request('/api/ppt-shares','POST',{course:'pamm',hours:24,confirm:true});assert.equal(issued.status,201);
  const managed=await admin.request('/api/admin/ppt-shares/manage','POST',{id:issued.data.id,preapproved:true});assert.equal(managed.status,200);
  const bearer=new URLSearchParams(new URL(issued.data.url).hash.slice(1)).get('share');
  active=false;
  assert.equal((await reader.request('/api/ppt-shares','POST',{course:'pamm',hours:24,confirm:true})).status,402);
  assert.equal((await reader.request('/api/ppt-share-policy?course=pamm')).data.canShare,false);
  assert.equal((await admin.request('/api/admin/ppt-shares/manage','POST',{id:issued.data.id,hours:48})).status,402);
  const response=await fetch(f.base+'/api/ppt-public',{headers:{authorization:'Bearer '+bearer,'x-ppt-visitor':'a'.repeat(64)}}),result=await response.json();
  assert.equal(response.status,200);assert(result.material.lessons.length);assert.equal(result.hosting,undefined);assert.equal(issued.data.expires,null);assert(Math.abs(Date.parse(result.expires)-Date.now()-86400000)<2000);
  assert.equal((await fetch(f.base+'/_hosting/enter',{headers:{'x-hosting-identity':'admin@example.test'}})).status,404);
 }finally{await f.cleanup()}
});

