test('hosted Markdown enforcement covers preview, save and course creation without consuming credits',async()=>{let tier='basic';const f=await fixture({hosting:{allowLegacyAdmin:true,status:()=>({tier,active:true,limits:{courses:5,images:0,aiTokens:0}})}});try{const a=f.client();await a.login();assert.equal((await a.session()).data.uploadLimits.markdownBytes,2000000);const files=['zh','en'].map(x=>({filename:x+'.md',markdown:'a'.repeat(2000001)}));for(const preview of [true,false]){const result=await a.request('/api/admin/material-markdown','POST',{course:'pamm',baseVersion:1,files,preview});assert.equal(result.status,413);assert.equal(result.data.code,'markdown_too_large')}const result=await a.request('/api/admin/courses','POST',{title:{zh:'测试',en:'Test'},code:'safe-code',files});assert.equal(result.status,413);assert.equal(f.store.get("SELECT COUNT(*) n FROM space_usage WHERE kind='courses'").n,0);tier='advanced';assert.equal((await a.session()).data.uploadLimits.markdownBytes,10000000);const permitted=await a.request('/api/admin/material-markdown','POST',{course:'pamm',baseVersion:1,filename:'test.md',markdown:'a'.repeat(2000001),preview:true});assert.equal(permitted.status,400);assert.match(permitted.data.error,/three lesson/);assert.equal(f.store.get("SELECT draft FROM courses WHERE id='pamm'").draft,1)}finally{await f.cleanup()}});


test('PPT validity starts independently on each recipient first approved opening, never on creation, checks or refresh',async()=>{const f=await fixture();try{const admin=f.client(),learner=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await learner.select();f.store.set('pptPolicy:pamm',{allowAll:true,maxHours:168});const issued=await learner.request('/api/ppt-shares','POST',{course:'pamm',hours:2,confirm:true});const bearer=new URLSearchParams(new URL(issued.data.url).hash.slice(1)).get('share'),read=async(v,check=false)=>{const r=await fetch(f.base+'/api/ppt-public'+(check?'?check=1':''),{headers:{authorization:'Bearer '+bearer,'x-ppt-visitor':v.repeat(64)}});return r.json()};assert((await read('a')).approvalRequired);assert.equal(f.store.get('SELECT COUNT(*) n FROM ppt_read_windows').n,0);await admin.request('/api/admin/ppt-shares/manage','POST',{id:issued.data.id,preapproved:true});let now=new Date(Date.now()+3*86400000).toISOString();f.store.now=()=>now;const checked=await read('a',true);assert(checked.readyToStart);assert(!checked.material);assert.equal(f.store.get('SELECT COUNT(*) n FROM ppt_read_windows').n,0);const a=await read('a');assert(a.material);assert.equal(Date.parse(a.expires)-Date.parse(now),7200000);now=new Date(Date.parse(now)+3600000).toISOString();const b=await read('b');assert.equal(Date.parse(b.expires)-Date.parse(a.expires),3600000);assert.equal((await read('a')).expires,a.expires);now=new Date(Date.parse(a.expires)+1).toISOString();assert((await read('a')).expired);assert(!(await read('b')).expired);assert.equal(f.store.get('SELECT COUNT(*) n FROM ppt_read_windows').n,2)}finally{await f.cleanup()}});


test('course picker limits discovery to own history and grants, and rechecks access on ID switching',async()=>{const f=await fixture();try{const admin=f.client(),learner=f.client(),other=f.client(),anon=f.client(false);await admin.login();const material=(await admin.request('/api/admin/material?course=pamm')).data.material;await admin.request('/api/admin/courses','POST',{id:'second',code:'second-code',title:{zh:'第二',en:'Second'}});await admin.request('/api/admin/material','PUT',{course:'second',baseVersion:0,material});await admin.request('/api/admin/publish','POST',{course:'second',version:1});await learner.select();assert.deepEqual((await learner.request('/api/my-courses')).data.map(c=>c.id),['pamm']);assert.equal((await learner.request('/api/switch-course','POST',{course:'second'})).status,403);assert.equal((await learner.session()).data.course.id,'pamm');await learner.request('/api/switch-course','POST',{code:'second-code'});await learner.request('/api/switch-course','POST',{course:'pamm'});let list=(await learner.request('/api/my-courses')).data;assert.equal(list.length,2);assert(list.every(c=>!('code' in c)&&!('code_hash' in c)&&!('material' in c)));const switched=await learner.request('/api/switch-course','POST',{course:'second'});assert.equal(switched.status,200);assert.equal(switched.data.allowed,false);assert.equal((await learner.request('/api/course')).status,403);await other.select();assert.equal((await other.request('/api/my-courses')).data.length,1);assert.equal((await admin.request('/api/my-courses')).data.length,2);await anon.session();assert.equal((await anon.request('/api/my-courses')).status,401);await admin.request('/api/admin/course','PATCH',{id:'second',enabled:false});assert.equal((await learner.request('/api/switch-course','POST',{course:'second'})).status,403);assert.equal((await learner.request('/api/my-courses')).data.some(c=>c.id==='second'),false)}finally{await f.cleanup()}});

test('course picker discovers instructor assignments without codes and removes revoked grants',async()=>{const f=await fixture();try{const admin=f.client(),teacher=f.client();await admin.login();const account=(await admin.request('/api/admin/instructors','POST',{username:'picker.teacher',name:'Teacher',password:'picker-teacher-password-987',hours:24})).data;await admin.request('/api/admin/instructor-grants','PUT',{instructor:account.id,course:'pamm',hours:24,capabilities:{}});await teacher.session();await teacher.request('/api/instructor/login','POST',{username:'picker.teacher',password:'picker-teacher-password-987'});const list=(await teacher.request('/api/my-courses')).data;assert.equal(list.length,1);assert.equal(list[0].role,'instructor');assert.equal(list[0].allowed,true);assert.equal((await teacher.request('/api/switch-course','POST',{course:'pamm'})).data.allowed,true);await admin.request('/api/admin/instructor-grants','DELETE',{instructor:account.id,course:'pamm'});assert.equal((await teacher.request('/api/my-courses')).data[0].allowed,false);assert.equal((await teacher.request('/api/course')).status,403)}finally{await f.cleanup()}});

test('profile security requires current secret, preserves content and revokes other sessions',async()=>{const f=await fixture();try{const a=f.client(),b=f.client(),admin=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await a.request('/api/note','PUT',{page:'manager-01',body:'Preserve note'});const me=(await a.session()).data.user;await b.session();await b.request('/api/access','POST',{code:'pamm',contact:me.email,name:'Same',consent:true});const before=f.store.get('SELECT secret_hash FROM account_security WHERE user_id=?',me.id).secret_hash;assert.equal((await a.request('/api/profile/security','PUT',{method:'security',current:'wrong',mode:'password',secret:'new-secret-123',confirm:'new-secret-123'})).status,401);assert.equal(f.store.get('SELECT secret_hash FROM account_security WHERE user_id=?',me.id).secret_hash,before);assert.equal((await a.request('/api/profile/security','PUT',{method:'security',current:'test-security-password-987',mode:'question',question:'Favourite place?',secret:'上海浦东',confirm:'上海浦东'})).status,200);assert.equal((await a.request('/api/note?page=manager-01')).data.body,'Preserve note');assert.equal((await b.request('/api/course')).status,401);const config=(await a.request('/api/profile/security')).data;assert.equal(config.methods[0].question,'Favourite place?');assert(!JSON.stringify(config).includes('secret_hash'));assert.equal((await a.request('/api/profile/security','PUT',{method:'password',current:password,secret:'some-other-password',confirm:'some-other-password'})).status,401);assert.equal((await admin.request('/api/profile/security','PUT',{method:'password',current:password,secret:'new-root-password-12345',confirm:'new-root-password-12345'})).status,200);assert.equal((await admin.request('/api/admin/users')).status,200)}finally{await f.cleanup()}});

test('administrator can reauthorize personal access and adjust its expiry without broadening to IP',async()=>{const f=await fixture();try{const a=f.client(),admin=f.client();await a.select();await admin.login();const r=await a.request('/api/requests','POST',{});await admin.request('/api/admin/requests','POST',{id:r.data.id,status:'approved',hours:24});await admin.request('/api/admin/revoke','POST',{id:r.data.id});assert.equal((await a.request('/api/course')).status,403);const re=await admin.request('/api/admin/requests','POST',{id:r.data.id,status:'approved',hours:3});assert.equal(re.status,200);assert(Date.parse(re.data.expires)-Date.now()<3*3600000+1000);assert.equal((await a.request('/api/course')).status,200);const adjusted=await admin.request('/api/admin/requests','POST',{id:r.data.id,status:'approved',hours:1});assert.equal(adjusted.status,200);assert(Date.parse(adjusted.data.expires)<Date.parse(re.data.expires));assert.equal(f.store.get('SELECT COUNT(*) n FROM whitelist').n,0);assert.equal((await a.request('/api/admin/requests','POST',{id:r.data.id,status:'approved',hours:12})).status,403);assert.equal((await admin.request('/api/admin/requests','POST',{id:r.data.id,status:'approved',hours:0})).status,400)}finally{await f.cleanup()}});

test('PPT reauthorization resets one reader and duration adjustments preserve its start without changing others',async()=>{const f=await fixture();try{const admin=f.client(),learner=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await learner.select();f.store.set('pptPolicy:pamm',{allowAll:true,maxHours:168});const issued=await learner.request('/api/ppt-shares','POST',{course:'pamm',hours:24,confirm:true,creatorEmail:'owner@example.test',creatorName:'Owner'});assert.equal(issued.status,201);const id=issued.data.id,bearer=new URLSearchParams(new URL(issued.data.url).hash.slice(1)).get('share');for(const [v,email]of [['a','a@example.test'],['b','b@example.test']])f.store.run('INSERT INTO ppt_visitors VALUES(?,?,?,?,?,?,?,?,?,?)',v,id,crypto.createHash('sha256').update(v.repeat(64)).digest('hex'),v,email,'127.0.0.1','pending',f.store.now(),null,null);
 const decide=(who,decision,hours)=>admin.request('/api/admin/ppt-visitors/decision','POST',{id:who,decision,hours});const read=async v=>(await fetch(f.base+'/api/ppt-public',{headers:{authorization:'Bearer '+bearer,'x-ppt-visitor':v.repeat(64)}})).json();await decide('a','approve',4);await decide('b','approve',6);const first=await read('a'),other=await read('b');assert(first.material);await decide('a','adjust',2);const adjusted=await read('a');assert.equal(adjusted.started,first.started);assert.equal(Date.parse(adjusted.expires)-Date.parse(first.started),7200000);assert.equal((await read('b')).expires,other.expires);await decide('a','revoke');assert(!(await read('a')).material);assert.equal((await decide('a','approve')).status,200);await decide('a','revoke');assert.equal((await decide('a','approve',3)).status,200);const renewed=await read('a');assert(renewed.material);assert.equal(Date.parse(renewed.expires)-Date.parse(renewed.started),10800000);await admin.request('/api/ppt-shares','DELETE',{id});assert.equal((await decide('a','approve',3)).status,409);assert.equal((await admin.request('/api/admin/ppt-shares/manage','POST',{id,restore:true,hours:5})).status,200);assert((await read('a')).material);assert.equal((await admin.request('/api/admin/ppt-shares/manage','POST',{id,restore:true,hours:5})).status,409);
 }finally{await f.cleanup()}});


test('course search combines bilingual published material, approved knowledge and visible discussions without model requests',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client(),b=f.client();await admin.login();await admin.request('/api/admin/whitelist','POST',{course:'pamm',cidr:'127.0.0.1'});await a.select();await b.select();
 const doc=(await admin.request('/api/preparation','POST',{course:'pamm',title:'SEARCHREF',kind:'reference',raw:'SEARCHREF approved knowledge 数据核对'})).data;
 assert(doc.id);await admin.request('/api/preparation/knowledge','POST',{course:'pamm',id:doc.id,approved:true,confirm:true,baseRevision:1,basePublished:1});
 const hidden=(await admin.request('/api/preparation','POST',{course:'pamm',title:'HIDDENREF',kind:'reference',raw:'HIDDENREF private source'})).data;
 const publicQ=(await a.request('/api/questions','POST',{page:'manager-01',body:'SEARCHQUESTION shared question'})).data;
 await a.request('/api/questions','POST',{page:'manager-01',body:'PRIVATESEARCH private question',visibility:'private'});
 await a.request('/api/questions','POST',{page:'manager-01',body:'STAFFSEARCH instructor question',visibility:'staff'});
 const {businessVersions}=await import('../src/business-versions.mjs'),{courseKnowledge}=await import('../src/course-knowledge.mjs'),{digest}=await import('../src/security.mjs');const business=businessVersions(f.store),c=business.resolve(f.store.get("SELECT * FROM courses WHERE id='pamm'"),{admin:false},'v1'),kb=courseKnowledge(f.store,{material:x=>business.scope(x,business.read(x,x.published))});
 f.store.run("INSERT OR REPLACE INTO ai_answers(question_id,status,body,sources,business,revision,fingerprint,updated,knowledge_signature,translations) VALUES(?,'answered',?,'[]','v1',1,?,?,?,?)",publicQ.id,'中文可靠解释',digest('SEARCHQUESTION shared question'),f.store.now(),kb.signature(c),JSON.stringify({zh:'中文可靠解释',en:'UNIQUEAIWORD bilingual answer'}));
 assert.equal((await b.request('/api/course-search?q=UNIQUEAIWORD')).data.items[0].id,publicQ.id);
 f.store.run("UPDATE ai_answers SET fingerprint='outdated' WHERE question_id=?",publicQ.id);assert.equal((await b.request('/api/course-search?q=UNIQUEAIWORD')).data.total,0);
 let result=await b.request('/api/course-search?q=SEARCHQUESTION');assert.equal(result.status,200,JSON.stringify(result.data));assert(result.data.items.some(r=>r.id===publicQ.id));
 assert.equal((await b.request('/api/course-search?q=PRIVATESEARCH')).data.total,0);assert.equal((await b.request('/api/course-search?q=STAFFSEARCH')).data.total,0);assert.equal((await a.request('/api/course-search?q=PRIVATESEARCH')).data.total,1);
 assert.equal((await b.request('/api/course-search?q=SEARCHREF')).data.items[0].type,'knowledge');assert.equal((await b.request('/api/course-search?q=HIDDENREF')).data.total,0);assert.equal((await b.request('/api/course-search/source?type=knowledge&id='+hidden.id)).status,404);
 const m=(await b.request('/api/course')).data.material;const phrase=m.lessons[0].pages[0].title.en;assert((await b.request('/api/course-search?q='+encodeURIComponent(phrase))).data.items.some(r=>r.type==='material'));
 const detail=(await b.request('/api/course-search/source?type=material&id=manager-01')).data;assert(detail.body.en);assert(!JSON.stringify(detail).includes('speaker'));
 await admin.request('/api/preparation/knowledge','POST',{course:'pamm',id:doc.id,approved:false});assert.equal((await b.request('/api/course-search?q=SEARCHREF')).data.total,0);assert.equal((await b.request('/api/course-search/source?type=knowledge&id='+doc.id)).status,404);
 const guest=f.client();await guest.session();assert.notEqual((await guest.request('/api/course-search?q=SEARCHQUESTION')).status,200);
 }finally{await f.cleanup()}});

test('access insight sorting uses authorized course activity and recalculates remaining duration',async()=>{const f=await fixture();try{const admin=f.client(),a=f.client();await admin.login();await a.select();await a.request('/api/requests','POST',{});const r=f.store.get('SELECT * FROM requests');await admin.request('/api/admin/requests','POST',{id:r.id,status:'approved',hours:3});await a.request('/api/course');await a.request('/api/events','POST',{id:uid(),page:'manager-01',version:1,kind:'view',language:'en',tab:'insights'});f.store.run('UPDATE read_state SET stamp=? WHERE user_id=?',Date.now()-10000,r.user_id);await a.request('/api/events','POST',{id:uid(),page:'manager-01',version:1,kind:'heartbeat',language:'en',tab:'insights'});const out=await admin.request('/api/admin/requests?sort=seconds&direction=desc');assert.equal(out.status,200);assert.equal(out.data[0].visits,1);assert(out.data[0].seconds>=9);assert(out.data[0].remainingSeconds>10700);await admin.request('/api/admin/revoke','POST',{id:r.id});assert.equal((await admin.request('/api/admin/requests?status=revoked')).data[0].remainingSeconds,0);assert.equal((await a.request('/api/admin/requests')).status,403);}finally{await f.cleanup()}});


test('automatic course campaigns grant once after security, respect boundaries and preserve revocation',async()=>{const f=await fixture();try{const admin=f.client(),learner=f.client(false),old=f.client(),other=f.client();await admin.login();const defaults=(await admin.request('/api/admin/access-campaign?course=pamm')).data;assert.equal(defaults.enabled,false);assert.equal(defaults.hours,24);await old.select();
 const campaign={course:'pamm',enabled:true,startsAt:new Date(Date.now()-60000).toISOString(),endsAt:new Date(Date.now()+60000).toISOString(),hours:24,revision:0};assert.equal((await admin.request('/api/admin/access-campaign','POST',campaign)).status,200);
 await learner.select();assert.equal(f.store.get('SELECT COUNT(*) n FROM automatic_access_grants').n,0);assert.equal((await learner.request('/api/course')).status,401);const verified=await learner.request('/api/security/complete','POST',{mode:'password',secret:'campaign-secret-123',confirm:'campaign-secret-123'});assert.equal(verified.status,200);assert.equal(verified.data.allowed,true);const grant=f.store.get("SELECT * FROM requests WHERE actor='automatic:first-visit'");assert(grant);assert(Math.abs(Date.parse(grant.expires)-Date.now()-86400000)<5000);assert.equal(f.store.get('SELECT COUNT(*) n FROM whitelist').n,0);await learner.session();await learner.session();assert.equal(f.store.get('SELECT COUNT(*) n FROM automatic_access_grants').n,1);assert.equal((await old.session()).data.allowed,false);f.store.run('UPDATE requests SET expires=? WHERE id=?',new Date(Date.now()-1000).toISOString(),grant.id);assert.equal((await learner.session()).data.allowed,false);assert.equal(f.store.get('SELECT COUNT(*) n FROM automatic_access_grants').n,1);assert.equal((await learner.request('/api/admin/access-campaign?course=pamm')).status,403);assert.equal((await learner.request('/api/admin/access-campaign','POST',campaign)).status,403);
 assert.equal((await admin.request('/api/admin/requests')).data.find(r=>r.id===grant.id).automatic,1);const expired=(await admin.request('/api/admin/requests?source=automatic&status=expired')).data;assert.equal(expired.length,1);assert.equal(expired[0].effectiveStatus,'expired');assert.equal((await admin.request('/api/admin/requests?source=automatic&status=approved')).data.length,0);assert.equal((await admin.request('/api/admin/requests?source=manual')).data.some(r=>r.id===grant.id),false);await admin.request('/api/admin/revoke','POST',{id:grant.id});assert.equal((await admin.request('/api/admin/requests?source=automatic&status=revoked')).data[0].effectiveStatus,'revoked');await learner.session();assert.equal((await learner.request('/api/course')).status,403);assert.equal(f.store.get('SELECT COUNT(*) n FROM automatic_access_grants').n,1);
 assert.equal((await admin.request('/api/admin/access-campaign','POST',{...campaign,hours:12,revision:0})).status,409);assert.equal((await admin.request('/api/admin/access-campaign','POST',{...campaign,hours:0,revision:1})).status,400);assert.equal((await admin.request('/api/admin/access-campaign','POST',{...campaign,endsAt:campaign.startsAt,revision:1})).status,400);
 await admin.request('/api/admin/access-campaign','POST',{...campaign,enabled:false,revision:1});await other.select();assert.equal((await other.session()).data.allowed,false);
 }finally{await f.cleanup()}});

test('campaign time window is start-inclusive/end-exclusive and one-time per course',async()=>{const f=await fixture();try{const {accessCampaigns}=await import('../src/access-campaigns.mjs');const campaigns=accessCampaigns(f.store),c=f.store.get("SELECT * FROM courses WHERE id='pamm'"),start='2030-01-01T00:00:00.000Z',end='2030-01-02T00:00:00.000Z';const oldNow=f.store.now;campaigns.save({course:c.id,enabled:true,startsAt:start,endsAt:end,hours:3,revision:0},'admin');const s=id=>({user_id:id,ip:'192.0.2.1',device_hash:id});for(const id of ['before','start','end'])f.store.run('INSERT INTO users(id,device_hash,created) VALUES(?,?,?)',id,id,oldNow());f.store.now=()=>new Date(Date.parse(start)-1).toISOString();assert.equal(campaigns.firstVisit(s('before'),c),null);f.store.now=()=>start;assert(campaigns.firstVisit(s('start'),c));assert.equal(campaigns.firstVisit(s('before'),c),null);f.store.now=()=>end;assert.equal(campaigns.firstVisit(s('end'),c),null);f.store.run("INSERT INTO courses SELECT 'other',title,code_hash,'other-lookup',published,draft,enabled,created FROM courses WHERE id='pamm'");const other=f.store.get("SELECT * FROM courses WHERE id='other'");f.store.now=()=>start;assert.equal(campaigns.firstVisit(s('end'),other),null);campaigns.save({course:'other',enabled:true,startsAt:start,endsAt:end,hours:5,revision:0},'admin');assert(campaigns.firstVisit(s('start'),other));assert.equal(campaigns.firstVisit(s('end'),other),null);f.store.now=oldNow;
 }finally{await f.cleanup()}});
